/* eslint-disable func-style */
/* eslint-disable max-len */
/* eslint-disable require-jsdoc */


function addBlocks (Blockly) {

    // ── 各模块主题色 ──────────────────────────────
    // 交互控制类
    const COLOR_BUTTON  = '#2E7D32';   // 深绿色
    // 输出执行类（统一橙色）
    const COLOR_LED     = '#FB8C00';   // 橙色
    const COLOR_RGB     = '#FB8C00';   // 橙色
    const COLOR_BUZZER  = '#FB8C00';   // 橙色
    // 传感器输入类（统一深蓝色）
    const COLOR_KNOB    = '#1565C0';   // 深蓝色
    const COLOR_LIGHT   = '#1565C0';   // 深蓝色
    const COLOR_LM35    = '#1565C0';   // 深蓝色
    // 独立颜色
    const COLOR_DHT11   = '#00897B';   // 青绿色（温湿度专属）
    const COLOR_IR      = '#6A1B9A';   // 深紫色（红外专属）

    // ── 各模块专属产品图标 ────────────────────────
    const iconButton = 'data:image/svg+xml;base64,';
    const iconLed = 'data:image/svg+xml;base64,';
    const iconRgb = 'data:image/svg+xml;base64,';
    const iconDht11 = 'data:image/svg+xml;base64,';
    const iconKnob = 'data:image/svg+xml;base64,';
    const iconLight = 'data:image/svg+xml;base64,';
    const iconLm35 = 'data:image/svg+xml;base64,';
    const iconBuzzer = 'data:image/svg+xml;base64,';
    const iconIr = 'data:image/svg+xml;base64,';

    // ─────────────────────────────────────────────
    // 1. 按键读取 (SW1=D2, SW2=D7)
    // ─────────────────────────────────────────────
    Blockly.Blocks.tdr_button_read = {
        init: function () {
            this.jsonInit({
                message0: '%1',
                message1: Blockly.Msg.TDR_BUTTON_READ,
                args0: [{ type: 'field_image', src: iconButton, width: 40, height: 22 }],
                args1: [
                    {
                        type: 'field_dropdown',
                        name: 'BTN',
                        options: [
                            ['SW1 (D2)', '2'],
                            ['SW2 (D7)', '7']
                        ]
                    }
                ],
                colour: COLOR_BUTTON,
                extensions: ['output_boolean']
            });
        }
    };

    // ─────────────────────────────────────────────
    // 2. 单色 LED 控制 (D12 / D13)
    // ─────────────────────────────────────────────
    Blockly.Blocks.tdr_led_set = {
        init: function () {
            this.jsonInit({
                message0: '%1',
                message1: Blockly.Msg.TDR_LED_SET,
                args0: [{ type: 'field_image', src: iconLed, width: 40, height: 22 }],
                args1: [
                    {
                        type: 'field_dropdown',
                        name: 'LED',
                        options: [
                            ['红色 Led1 (D12)', '12'],
                            ['蓝色 Led3 (D13)', '13']
                        ]
                    },
                    {
                        type: 'field_dropdown',
                        name: 'STATE',
                        options: [
                            [Blockly.Msg.TDR_ON,  'HIGH'],
                            [Blockly.Msg.TDR_OFF, 'LOW']
                        ]
                    }
                ],
                colour: COLOR_LED,
                extensions: ['shape_statement']
            });
        }
    };

    // ─────────────────────────────────────────────
    // 3. RGB LED 控制 (R=D6, G=D9, B=D10)
    // ─────────────────────────────────────────────
    Blockly.Blocks.tdr_rgb_set = {
        init: function () {
            this.jsonInit({
                message0: '%1',
                message1: Blockly.Msg.TDR_RGB_SET,
                args0: [{ type: 'field_image', src: iconRgb, width: 40, height: 22 }],
                args1: [
                    { type: 'input_value', name: 'R' },
                    { type: 'input_value', name: 'G' },
                    { type: 'input_value', name: 'B' }
                ],
                colour: COLOR_RGB,
                extensions: ['shape_statement']
            });
        }
    };

    // ─────────────────────────────────────────────
    // 4. DHT11 温湿度传感器 (D4)
    // ─────────────────────────────────────────────
    Blockly.Blocks.tdr_dht11_read = {
        init: function () {
            this.jsonInit({
                message0: '%1',
                message1: Blockly.Msg.TDR_DHT11_READ,
                args0: [{ type: 'field_image', src: iconDht11, width: 40, height: 22 }],
                args1: [
                    {
                        type: 'field_dropdown',
                        name: 'TYPE',
                        options: [
                            [Blockly.Msg.TDR_TEMPERATURE, 'temperature'],
                            [Blockly.Msg.TDR_HUMIDITY,    'humidity']
                        ]
                    }
                ],
                colour: COLOR_DHT11,
                extensions: ['output_number']
            });
        }
    };

    // ─────────────────────────────────────────────
    // 5. 旋转电位器读取 (A0)
    // ─────────────────────────────────────────────
    Blockly.Blocks.tdr_rotation_read = {
        init: function () {
            this.jsonInit({
                message0: '%1',
                message1: Blockly.Msg.TDR_ROTATION_READ,
                args0: [{ type: 'field_image', src: iconKnob, width: 40, height: 22 }],
                args1: [],
                colour: COLOR_KNOB,
                extensions: ['output_number']
            });
        }
    };

    // ─────────────────────────────────────────────
    // 6. 光敏传感器读取 (A1)
    // ─────────────────────────────────────────────
    Blockly.Blocks.tdr_light_read = {
        init: function () {
            this.jsonInit({
                message0: '%1',
                message1: Blockly.Msg.TDR_LIGHT_READ,
                args0: [{ type: 'field_image', src: iconLight, width: 40, height: 22 }],
                args1: [],
                colour: COLOR_LIGHT,
                extensions: ['output_number']
            });
        }
    };

    // ─────────────────────────────────────────────
    // 7. LM35 温度传感器读取 (A2)
    // ─────────────────────────────────────────────
    Blockly.Blocks.tdr_lm35_read = {
        init: function () {
            this.jsonInit({
                message0: '%1',
                message1: Blockly.Msg.TDR_LM35_READ,
                args0: [{ type: 'field_image', src: iconLm35, width: 40, height: 22 }],
                args1: [],
                colour: COLOR_LM35,
                extensions: ['output_number']
            });
        }
    };

    // ─────────────────────────────────────────────
    // 8. 蜂鸣器 - 播放音调 (D8)
    // ─────────────────────────────────────────────
    Blockly.Blocks.tdr_buzzer_tone = {
        init: function () {
            this.jsonInit({
                message0: '%1',
                message1: Blockly.Msg.TDR_BUZZER_TONE,
                args0: [{ type: 'field_image', src: iconBuzzer, width: 40, height: 22 }],
                args1: [
                    { type: 'input_value', name: 'FREQ' },
                    { type: 'input_value', name: 'DURATION' }
                ],
                colour: COLOR_BUZZER,
                extensions: ['shape_statement']
            });
        }
    };

    // ─────────────────────────────────────────────
    // 9. 蜂鸣器 - 停止 (D8)
    // ─────────────────────────────────────────────
    Blockly.Blocks.tdr_buzzer_stop = {
        init: function () {
            this.jsonInit({
                message0: '%1',
                message1: Blockly.Msg.TDR_BUZZER_STOP,
                args0: [{ type: 'field_image', src: iconBuzzer, width: 40, height: 22 }],
                args1: [],
                colour: COLOR_BUZZER,
                extensions: ['shape_statement']
            });
        }
    };

    // ─────────────────────────────────────────────
    // 10. 蜂鸣器 - 播放预设音乐 (D8)
    // ─────────────────────────────────────────────
    Blockly.Blocks.tdr_buzzer_music = {
        init: function () {
            this.jsonInit({
                message0: '%1',
                message1: Blockly.Msg.TDR_BUZZER_MUSIC,
                args0: [{ type: 'field_image', src: iconBuzzer, width: 40, height: 22 }],
                args1: [
                    {
                        type: 'field_dropdown',
                        name: 'SONG',
                        options: [
                            [Blockly.Msg.TDR_SONG_BIRTHDAY, 'BIRTHDAY'],
                            [Blockly.Msg.TDR_SONG_JINGLE,   'JINGLE'],
                            [Blockly.Msg.TDR_SONG_MARIO,    'MARIO']
                        ]
                    }
                ],
                colour: COLOR_BUZZER,
                extensions: ['shape_statement']
            });
        }
    };

    // ─────────────────────────────────────────────
    // 11. 红外接收 - 是否收到信号 (D11)
    // ─────────────────────────────────────────────
    Blockly.Blocks.tdr_ir_received = {
        init: function () {
            this.jsonInit({
                message0: '%1',
                message1: Blockly.Msg.TDR_IR_RECEIVED,
                args0: [{ type: 'field_image', src: iconIr, width: 40, height: 22 }],
                args1: [],
                colour: COLOR_IR,
                extensions: ['output_boolean']
            });
        }
    };

    // ─────────────────────────────────────────────
    // 12. 红外接收 - 读取键值 (D11)
    // ─────────────────────────────────────────────
    Blockly.Blocks.tdr_ir_read_value = {
        init: function () {
            this.jsonInit({
                message0: '%1',
                message1: Blockly.Msg.TDR_IR_READ_VALUE,
                args0: [{ type: 'field_image', src: iconIr, width: 40, height: 22 }],
                args1: [],
                colour: COLOR_IR,
                extensions: ['output_number']
            });
        }
    };

    return Blockly;
}

exports = addBlocks;
